61	import org.springframework.web.bind.annotation.RestController;
62	import org.springframework.web.util.UriComponentsBuilder;
63	
64	import jakarta.transaction.Transactional;
65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /** Maximum number of owners a single city may contain; creating an owner in a city that
76	     *  already has this many owners is rejected with 409 Conflict. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created on a single day (by registration date); creating
80	     *  an owner once this many owners already carry today's registration date is rejected with
81	     *  429 Too Many Requests. */
82	    private static final int MAX_OWNERS_PER_DAY = 100;
83	
84	    /** When more than this many owners already carry today's registration date at creation time, the
85	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
86	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
87	
88	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
89	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    private final ClinicService clinicService;
97	
98	    private final OwnerMapper ownerMapper;
99	
100	    private final PetMapper petMapper;
101	
102	    private final VisitMapper visitMapper;
103	
104	    private final TelephoneNormalizer telephoneNormalizer;
105	
106	    private final HouseholdNormalizer householdNormalizer;
107	
108	    private final AddressNormalizer addressNormalizer;
109	
110	    private final EmailNormalizer emailNormalizer;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper,
116	                                 TelephoneNormalizer telephoneNormalizer,
117	                                 HouseholdNormalizer householdNormalizer,
118	                                 AddressNormalizer addressNormalizer,
119	                                 EmailNormalizer emailNormalizer) {
120	        this.clinicService = clinicService;
121	        this.ownerMapper = ownerMapper;
122	        this.petMapper = petMapper;
123	        this.visitMapper = visitMapper;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.householdNormalizer = householdNormalizer;
126	        this.addressNormalizer = addressNormalizer;
127	        this.emailNormalizer = emailNormalizer;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        normalizeOwnerFields(owner);
161	        // Enforce the pre-persistence policies that can reject the new owner outright.
162	        rejectDisallowedOwnerCreation(owner);
163	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
164	        // function of last name and postcode), reject a household duplicate unless the request
165	        // declares it shares the household, and record the household size. This runs before the
166	        // identity-key check so that check sees the owner's household id.
167	        boolean declaredHouseholdMember =
168	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
169	        // Reject the create when the owner's whole derived identity key (normalized telephone,
170	        // email and household id) already matches an existing owner. This single rule subsumes the
171	        // former separate telephone, email and household duplicate checks.
172	        rejectWhenIdentityInUse(owner);
173	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
174	        // shares an existing owner's last name and postcode with a different telephone. A declared
175	        // household member is never flagged: it is a known member, not a suspected duplicate.
176	        assignPossibleDuplicate(owner, declaredHouseholdMember);
177	        // Assign the remaining create-time derived fields (namesake count, customer code,
178	        // membership number and bulk-signup warning), each fixed at creation time.
179	        assignDerivedFields(owner);
180	        this.clinicService.saveOwner(owner);
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        // Emit an audit line for the successful create, carrying the owner id, customer code,
183	        // registration date, membership level and membership number so the create can be traced
184	        // from the dedicated AUDIT log.
185	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
186	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
187	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
188	        headers.setLocation(UriComponentsBuilder.newInstance()
189	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
190	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    /**
194	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
195	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
196	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
197	     * the sequence of create-time rejections stays readable and a new rule is added as one more
198	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
199	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
200	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
201	     * the household id has been resolved, because that key includes the household id.
202	     *
203	     * @param owner the newly mapped and normalized owner being created
204	     */
205	    private void rejectDisallowedOwnerCreation(Owner owner) {
206	        rejectWhenDailyLimitReached(owner);
207	        rejectWhenCityAtCapacity(owner);
208	    }
209	
210	    /**
211	     * Applies the household-membership rules for a newly normalized owner being created. The
212	     * household id is a deterministic function of the owner's last name and postcode, so owners
213	     * with the same last name and postcode share it automatically; it is assigned to the new owner
214	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
215	     * same last name and postcode is a member of the same household: a second such owner is rejected
216	     * as a household duplicate (409) unless the request declares it shares the household via
217	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
218	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
219	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
220	     * is resolved here before {@link #rejectWhenIdentityInUse}.
221	     *
222	     * @param owner           the newly mapped and normalized owner being created
223	     * @param sharesHousehold whether the request declared that the owner shares an existing household
224	     * @return {@code true} if the owner joined an existing household as a declared member
225	     */
226	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
227	        // Assign the deterministic household id (a pure function of last name and postcode) so every
228	        // owner with the same last name and postcode shares it automatically.
229	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
230	        // Identify any existing owners in the same household (same computed household id).
231	        List<Owner> householdMembers = sameHouseholdOwners(owner);
232	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
233	        // the request declares it shares the household, in which case create it as a declared member.
234	        boolean declaredHouseholdMember = false;
235	        if (!householdMembers.isEmpty()) {
236	            if (!sharesHousehold) {
237	                throw new HouseholdDuplicateException(
238	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
239	            }
240	            declaredHouseholdMember = true;
241	        }
242	        // Record the size of this owner's household after this create, fixed at creation time.
243	        owner.setHouseholdSize(householdMembers.size() + 1);
244	        return declaredHouseholdMember;
245	    }
246	
247	    /**
248	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
249	     * has already been resolved: the namesake count, the per-city customer code, the membership
250	     * number derived from that customer code and the registration year, and the bulk-signup warning
251	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
252	     * here keeps {@link #addOwner} focused on the high-level create sequence.
253	     *
254	     * @param owner the owner being created, already normalized and with its household resolved
255	     */
256	    private void assignDerivedFields(Owner owner) {
257	        // Record how many existing owners already share this owner's first and last name
258	        // (compared case-insensitively) before this create, fixed at creation time.
259	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
260	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
261	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
262	        // time.
263	        owner.setCustomerCode(customerCode(owner));
264	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
265	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
266	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
267	        // Flag the create when more than 80 owners have already been created on this owner's
268	        // (adjusted business-day) registration date, fixed at creation time.
269	        owner.setBulkSignupWarning(
270	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
271	    }
272	
273	    /**
274	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
275	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
276	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
277	     * the former separate telephone, email and household duplicate checks: two owners collide only
278	     * when their whole keys are equal, and members of one household with different telephones have
279	     * different keys and are both allowed.
280	     *
281	     * @param owner the owner being created, already normalized and with its household resolved
282	     */
283	    private void rejectWhenIdentityInUse(Owner owner) {
284	        String identityKey = owner.getIdentityKey();
285	        boolean inUse = existingOwners()
286	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
287	        if (inUse) {
288	            throw new DuplicateIdentityException(
289	                "An owner with identity key " + identityKey + " already exists");
290	        }
291	    }
292	
293	    /**
294	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
295	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
296	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
297	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
298	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
299	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
300	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
301	     * possible duplicate. A declared household member is never flagged: it is a known member of the
302	     * household, not a suspected duplicate. Both values are fixed at creation time.
303	     *
304	     * @param owner                   the owner being created, already normalized and confirmed not a
305	     *                                hard duplicate
306	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
307	     *                                member
308	     */
309	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
310	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
311	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
312	            .map(Owner::getId)
313	            .min(Integer::compareTo)
314	            .orElse(null);
315	        owner.setPossibleDuplicate(matchId != null);
316	        owner.setPossibleDuplicateOf(matchId);
317	    }
318	
319	    /**
320	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
321	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
322	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
323	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
324	     *
325	     * @param existing an existing owner to compare against
326	     * @param owner    the owner being created
327	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
328	     */
329	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
330	        return existing.getPostcode() != null
331	            && existing.getPostcode().equals(owner.getPostcode())
332	            && existing.getLastName() != null
333	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
334	            && existing.getTelephone() != null
335	            && !existing.getTelephone().equals(owner.getTelephone());
336	    }
337	
338	    /**
339	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
340	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
341	     *
342	     * @param owner the owner being created
343	     */
344	    private void rejectWhenDailyLimitReached(Owner owner) {
345	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
346	            throw new DailyOwnerLimitExceededException(
347	                "The maximum number of owners that may be created today has already been reached");
348	        }
349	    }
350	
351	    /**
352	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
353	     * or more owners, with 409 Conflict.
354	     *
355	     * @param owner the owner being created
356	     */
357	    private void rejectWhenCityAtCapacity(Owner owner) {
358	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
359	            throw new CityCapacityExceededException(
360	                "The city " + owner.getCity() + " already contains the maximum number of owners");
361	        }
362	    }
363	
364	    /**
365	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
366	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
367	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
368	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
369	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
370	     * server's current date. Canonicalising the address here, before the household checks read it,
371	     * ensures duplicate detection and the shared household id both compare the normalized form.
372	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
373	     * duplicate, household and customer-code rules.
374	     *
375	     * @param owner the newly mapped owner to canonicalize
376	     */
377	    private void normalizeOwnerFields(Owner owner) {
378	        // Canonicalize the owner's address fields on create so the address is stored and returned in
379	        // canonical form and every later comparison (household duplicate detection and the shared
380	        // household id) uses it. A value that is blank after normalization is rejected with 400.
381	        normalizeAddressFields(owner);
382	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
383	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
384	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
385	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
386	        // Store the (already syntactically validated) email lower-cased so it is persisted and
387	        // returned in canonical form. A missing email is left untouched.
388	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
389	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
390	        // canonicalization so the comparison sees the lower-cased value.
391	        rejectDisposableEmailDomain(owner.getEmail());
392	        // Validate the optional postcode against the fixed range for the city's region. A postcode
393	        // is checked only when present (it is optional); one out of range for the city's region is
394	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
395	        // value is left unchanged.
396	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
397	        // Reject a supplied registration date that is later than the server's current date with
398	        // 400, before any defaulting or business-day adjustment, so a future date is never
399	        // persisted regardless of how the roll-forward would move it.
400	        rejectFutureRegistrationDate(owner.getRegistrationDate());
401	        // Default the registration date to the server's current date when the client did not
402	        // supply one, then roll the effective date forward to a business day so a Saturday or
403	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
404	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
405	        // date-derived field (such as the membership number's year segment) and the per-day
406	        // create-limit are computed from.
407	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
408	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
409	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
410	    }
411	
412	    /**
413	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
414	     * returned in canonical form. The owner may supply its address in either of two forms and the
415	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
416	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
417	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
418	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
419	     * stored {@code address} is composed from the normalized structured lines when present — the
420	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
421	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
422	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
423	     * here, before the household checks read it, ensures duplicate detection and the shared household
424	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
425	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
426	     *
427	     * @param owner the newly mapped owner whose address is canonicalized
428	     */
429	    private void normalizeAddressFields(Owner owner) {
430	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
431	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
432	            owner.setAddressLine1(line1);
433	            String composed = line1;
434	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
435	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
436	                owner.setAddressLine2(line2);
437	                composed = line1 + " " + line2;
438	            }
439	            owner.setAddress(composed);
440	        }
441	        else {
442	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
443	        }
444	    }
445	
446	    /**
447	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
448	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
449	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
450	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
451	     * domain part is left untouched.
452	     *
453	     * @param email the owner's canonicalized email, or {@code null} when absent
454	     */
455	    private void rejectDisposableEmailDomain(String email) {
456	        if (email == null) {
457	            return;
458	        }
459	        int at = email.lastIndexOf('@');
460	        if (at < 0) {
461	            return;
462	        }
463	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
464	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
465	            throw new DisposableEmailException(
466	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
467	        }
468	    }
469	
470	    /**
471	     * Rejects a supplied registration date that is later than the server's current date with a
472	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
473	     * accepted, and a date on or before today is left for the normal defaulting and business-day
474	     * adjustment.
475	     *
476	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
477	     */
478	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
479	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
480	            throw new InvalidRegistrationDateException(
481	                "The supplied registration date " + registrationDate + " is later than the current date");
482	        }
483	    }
484	
485	    /**
486	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
487	     * following Monday, while a weekday is returned unchanged. Applied to the effective
488	     * registration date (whether supplied in the request or defaulted to the server date) so the
489	     * persisted registration date, every value derived from it and the per-day create-limit all
490	     * use the adjusted business day.
491	     *
492	     * @param date the effective registration date
493	     * @return the same date if it is a weekday, otherwise the following Monday
494	     */
495	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
496	        java.time.LocalDate adjusted = date;
497	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
498	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
499	            adjusted = adjusted.plusDays(1);
500	        }
501	        return adjusted;
502	    }
503	
504	    /**
505	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
506	     * region derived from the owner's postcode (falling back to the city, via
507	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
508	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
509	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
510	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
511	     * distinct customer codes.
512	     *
513	     * @param owner the owner being created, already normalized
514	     * @return the formatted, de-duplicated customer code
515	     */
516	    private String customerCode(Owner owner) {
517	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
518	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
519	        String base = region + "-" + hash8;
520	        Set<String> taken = existingOwners()
521	            .map(Owner::getCustomerCode)
522	            .filter(code -> code != null)
523	            .collect(Collectors.toSet());
524	        if (!taken.contains(base)) {
525	            return base;
526	        }
527	        int n = 2;
528	        while (taken.contains(base + "-" + n)) {
529	            n++;
530	        }
531	        return base + "-" + n;
532	    }
533	
534	    /**
535	     * Streams the existing owners that the create-time rules match a new owner against. Every
536	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
537	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
538	     * own matching criterion rather than on how the existing owners are retrieved.
539	     *
540	     * @return a stream over all existing owners
541	     */
542	    private Stream<Owner> existingOwners() {
543	        return this.clinicService.findAllOwners().stream();
544	    }
545	
546	    /**
547	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
548	     * fix the per-city sequence of an owner's customer code at creation time.
549	     *
550	     * @param city the city of the owner being created
551	     * @return the number of existing owners in a matching city
552	     */
553	    private int countOwnersInCity(String city) {
554	        return (int) existingOwners()
555	            .filter(existing -> existing.getCity() != null
556	                && existing.getCity().equalsIgnoreCase(city))
557	            .count();
558	    }
559	
560	    /**
561	     * Counts the existing owners whose registration date is the given adjusted business day. Used
562	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
563	     * owners already carry that business day as their registration date.
564	     *
565	     * @param date the adjusted business-day registration date to match
566	     * @return the number of existing owners registered on that date
567	     */
568	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
569	        return (int) existingOwners()
570	            .filter(existing -> date.equals(existing.getRegistrationDate()))
571	            .count();
572	    }
573	
574	    /**
575	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
576	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
577	     *
578	     * @param customerCode     the owner's customer code
579	     * @param registrationDate the owner's registration date
580	     * @return the formatted membership number
581	     */
582	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
583	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
584	    }
585	
586	    /**
587	     * Returns the existing owners in the given owner's household, i.e. those sharing its
588	     * deterministic household id (the same last name and postcode). The id is computed via
589	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
590	     * whitespace are treated as the same household. Centralising how "the same household" is matched
591	     * here keeps that definition in one place for every caller.
592	     *
593	     * @param owner the owner being created, with its household id already assigned
594	     * @return the existing owners in the owner's household (possibly empty)
595	     */
596	    private List<Owner> sameHouseholdOwners(Owner owner) {
597	        String householdId = owner.getHouseholdId();
598	        return existingOwners()
599	            .filter(existing -> householdId.equals(
600	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
601	            .toList();
602	    }
603	
604	    /**
605	     * Counts the existing owners who share the given first and last name, compared
606	     * case-insensitively. Used to fix an owner's namesake count at creation time.
607	     *
608	     * @param firstName the first name of the owner being created
609	     * @param lastName  the last name of the owner being created
610	     * @return the number of existing owners with a matching first and last name
611	     */
612	    private int countNamesakes(String firstName, String lastName) {
613	        return (int) existingOwners()
614	            .filter(existing -> existing.getFirstName() != null
615	                && existing.getFirstName().equalsIgnoreCase(firstName)
616	                && existing.getLastName() != null
617	                && existing.getLastName().equalsIgnoreCase(lastName))
618	            .count();
619	    }
620	
621	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
622	    @Override
623	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
624	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
625	        if (currentOwner == null) {
626	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
627	        }
628	        currentOwner.setAddress(ownerFieldsDto.getAddress());
629	        currentOwner.setCity(ownerFieldsDto.getCity());
630	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
631	        currentOwner.setLastName(ownerFieldsDto.getLastName());
632	        // Normalize the telephone to canonical E.164 form so it is stored and returned
633	        // consistently with create; an unformattable value is rejected with 400.
634	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
635	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
636	        this.clinicService.saveOwner(currentOwner);
637	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
638	    }
639	
640	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
641	    @Transactional
642	    @Override
643	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
644	        Owner owner = this.clinicService.findOwnerById(ownerId);
645	        if (owner == null) {
646	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
647	        }
648	        this.clinicService.deleteOwner(owner);
649	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
650	    }
651	
652	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
653	    @Override
654	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
655	        Owner owner = this.clinicService.findOwnerById(ownerId);
656	        if (owner == null) {
657	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
658	        }
659	        HttpHeaders headers = new HttpHeaders();
660	        Pet pet = petMapper.toPet(petFieldsDto);
661	        owner.setId(ownerId);
662	        pet.setOwner(owner);
663	        pet.getType().setName(null);
664	        this.clinicService.savePet(pet);
665	        PetDto petDto = petMapper.toPetDto(pet);
666	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
667	            .buildAndExpand(pet.getId()).toUri());
668	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
669	    }
670	
671	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
672	    @Override
673	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
674	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
675	        if (currentOwner != null) {
676	            Pet currentPet = this.clinicService.findPetById(petId);
677	            if (currentPet != null) {
678	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
679	                currentPet.setName(petFieldsDto.getName());
680	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
681	                this.clinicService.savePet(currentPet);
682	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
683	            }
684	        }
685	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
691	        HttpHeaders headers = new HttpHeaders();
692	        Visit visit = visitMapper.toVisit(visitFieldsDto);
693	        Pet pet = new Pet();
694	        pet.setId(petId);
695	        visit.setPet(pet);
696	        this.clinicService.saveVisit(visit);
697	        VisitDto visitDto = visitMapper.toVisitDto(visit);
698	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
699	            .buildAndExpand(visit.getId()).toUri());
700	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
701	    }
702	
703	
704	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
705	    @Override
706	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
707	        Owner owner = this.clinicService.findOwnerById(ownerId);
708	        if (owner != null) {
709	            Pet pet = owner.getPet(petId);
710	            if (pet != null) {
711	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
712	            }
713	        }
714	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
715	    }
716	}
