60	    /**
61	     * Returns the owner's canonical region (locality): the REGION segment of the customer code when
62	     * present, otherwise the region derived from the city and postcode, or {@code "UNKNOWN"}.
63	     */
64	    default String locality(Owner owner) {
65	        return owner.getCustomerCode() != null
66	            ? owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-'))
67	            : org.springframework.samples.petclinic.util.LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
68	    }
69	
70	    /**
71	     * Computes the owner's membership points: 0 to start, plus 2 when an email address is present,
72	     * plus 1 when the namesake count is 0, plus 2 for a household of 3 or more, and plus 3 for
73	     * tenure over 365 days.
74	     */
75	    default int membershipPoints(Owner owner) {
76	        int points = 0;
77	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
78	            points += 2;
79	        }
80	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
81	            points += 1;
82	        }
83	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
84	            points += 2;
85	        }
86	        if (owner.getRegistrationDate() != null
87	            && java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
88	            points += 3;
89	        }
90	        return points;
91	    }
