93	    /**
94	     * Maps membership points to a membership level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4
95	     * for 6 or more.
96	     */
97	    default int membershipLevel(int membershipPoints) {
98	        if (membershipPoints <= 1) {
